//! The third validation-layer gap a [`Messages`](super::Messages) sink lets pass: the layer's
//! synchronization validation does not read rasterization-order attachment access, and reports
//! an input attachment read that it orders as a hazard against an earlier draw's color write.
//!
//! A pipeline made with
//! `VK_PIPELINE_COLOR_BLEND_STATE_CREATE_RASTERIZATION_ORDER_ATTACHMENT_ACCESS_BIT_EXT` "forms a
//! framebuffer-local memory dependency for each fragment generated by draw commands for that
//! pipeline": its first synchronization scope "includes the
//! `VK_PIPELINE_STAGE_COLOR_ATTACHMENT_OUTPUT_BIT` pipeline stage executed by all previous
//! fragments (as defined by primitive order) in the corresponding framebuffer regions including
//! those generated by the same draw command", its second the fragment's
//! `VK_PIPELINE_STAGE_FRAGMENT_SHADER_BIT`, and its access scopes "all writes to color
//! attachments" and "all reads from input attachments" (the Framebuffer chapter,
//! `VkPipelineColorBlendStateCreateFlagBits`). The layer's synchronization code never reads that
//! flag: nothing in `layers/sync` names it, and `AccessState::DetectHazard` orders an input
//! attachment read only after a load op, "Input attachment is ordered against load op but not
//! against regular draws (requires subpass barrier)" (Vulkan-ValidationLayers v1.4.357, commit
//! e4786f7c, `layers/sync/sync_access_state.cpp` line 115; the same line in v1.4.363, commit
//! 2ea16de8; unchanged in main aea761f of 2026-10-18). So every fetch through an input attachment after an earlier draw wrote the pixel
//! reports a `READ_AFTER_WRITE`.
//!
//! The runtime fetches through input attachments where the device has
//! `rasterizationOrderColorAttachmentAccess` (`runtime/src/framebuffer_fetch.rs`), every pipeline
//! of such a pass made with that flag, and names each such pipeline [`NAME`] where its instance
//! reports messages (`runtime/src/pipeline/graphics.rs`, `RASTER_ORDER_PIPELINE`). [`shape`]
//! matches exactly that hazard, an input attachment read at the fragment shader after a color
//! attachment write by an earlier draw with no barrier between, and only when the pipeline it
//! names bears that name; [`read`] keys the layer releases whose source was read with the gap in
//! place. On any other release such a message fails, marked "re-read the input attachment
//! ordering in layer X.Y.Z", so a fixed or changed layer is checked again rather than trusted.

use ash::vk;

/// `messageIdNumber` of `SYNC-HAZARD-READ-AFTER-WRITE`, as the layer hashes its name.
const ID: i32 = -455515022;

/// The id name of the hazard.
const ID_NAME: &str = "SYNC-HAZARD-READ-AFTER-WRITE";

/// What follows the draw command the layer reports at: a read of an image view by the fragment
/// shader (`sync_reporting.cpp`, `FormatErrorMessage`, with `ImageDescriptorError`'s initiator).
const HAZARD: &str = "(): READ_AFTER_WRITE hazard detected. Shader stage \
    VK_SHADER_STAGE_FRAGMENT_BIT reads VkImageView 0x";

/// What follows the image view: the earlier write's command.
const PRIOR: &str = ", which was previously written by ";

/// What every draw command's name starts with.
const DRAW: &str = "vkCmdDraw";

/// The descriptor the view is read through (`PrepareCommonDescriptorMessage`).
const INPUT: &str = " (VK_DESCRIPTOR_TYPE_INPUT_ATTACHMENT)";

/// What names the bound pipeline, after the descriptor set.
const PIPELINE: &str = ", VkPipeline 0x";

/// What follows the pipeline.
const LAYOUT: &str = ", image layout ";

/// The end of the message: the read and the earlier write, with no barrier between them.
const ACCESSES: &str = "No sufficient synchronization is present to ensure that a read \
    (VK_ACCESS_2_INPUT_ATTACHMENT_READ_BIT) at VK_PIPELINE_STAGE_2_FRAGMENT_SHADER_BIT does not \
    conflict with a prior write (VK_ACCESS_2_COLOR_ATTACHMENT_WRITE_BIT) at \
    VK_PIPELINE_STAGE_2_COLOR_ATTACHMENT_OUTPUT_BIT.";

/// The note the layer puts before a message it reports for the last time
/// (`duplicate_message_limit`).
const LAST_TIME: &str = "(Warning - This VUID has now been reported ";

/// The runtime's name for a pipeline made with the flag (`runtime/src/pipeline/graphics.rs`,
/// `RASTER_ORDER_PIPELINE`), which the layer prints after the pipeline's handle.
pub(super) const NAME: &str =
    "metal2vulkan: a pipeline reading its input attachments in rasterization order";

/// The layer releases (`VkLayerProperties::specVersion` of `VK_LAYER_KHRONOS_validation`) whose
/// synchronization code was read with the gap in place: v1.4.357 (tag commit e4786f7c) and
/// v1.4.363 (tag commit 2ea16de8). In v1.4.363 the descriptor check moved
/// (`sync_command_buffer.cpp` line 589 to `sync_command.cpp` line 1335,
/// `ShaderAccessCommand::ValidateImageShaderAccess`) with its test unchanged: an input attachment
/// read is still found by `DetectAttachmentHazard` with `SyncOrdering::kRaster`, ordered by
/// `AccessState::DetectHazard` only after a load op (line 115), and no file of `layers/sync`
/// names the rasterization-order flags; the record-time message is made of the same text. What
/// v1.4.363 adds, the same hazard reported again at a submission's replay ("Shader stage ... in
/// vkCmdDraw... (from VkCommandBuffer ... submitted on the current VkQueue ...)"), is another
/// message, which [`shape`] does not take.
pub(super) const READ: &[u32] = &[
    vk::make_api_version(0, 1, 4, 357),
    vk::make_api_version(0, 1, 4, 363),
];

/// Where the gap is, for the line each message let pass prints.
pub(super) const SOURCE: &str = "Vulkan-ValidationLayers v1.4.357 (e4786f7c) and v1.4.363 \
    (2ea16de8) layers/sync/sync_access_state.cpp:115, AccessState::DetectHazard: \"Input attachment is \
    ordered against load op but not against regular draws (requires subpass barrier).\"; \
    layers/sync never reads the rasterization-order attachment access flags";

/// Whether a message with this id, id name and text is the gap's: a `READ_AFTER_WRITE` found at
/// a draw, the fragment shader's read of an input attachment after a color attachment write by
/// an earlier draw, with no barrier between, through a pipeline the runtime named [`NAME`].
pub(super) fn shape(id: i32, id_name: &str, text: &str) -> bool {
    if id != ID || id_name != ID_NAME {
        return false;
    }
    let Some(at) = text.find(HAZARD) else {
        return false;
    };
    // The draw command, alone on its line; before it, nothing or the layer's last-time note.
    let line = text[..at].rfind('\n').map_or(0, |end| end + 1);
    let command = &text[line..at];
    if !command.starts_with(DRAW) || !command.bytes().all(|b| b.is_ascii_alphanumeric()) {
        return false;
    }
    if line != 0 && !text.starts_with(LAST_TIME) {
        return false;
    }
    // The view, then the earlier write: a draw's (the same command's, "another" one).
    let Some(rest) = after_handle(&text[at + HAZARD.len()..]) else {
        return false;
    };
    let Some(rest) = rest.strip_prefix(PRIOR) else {
        return false;
    };
    let rest = rest.strip_prefix("another ").unwrap_or(rest);
    if !rest.starts_with(DRAW) {
        return false;
    }
    let Some(input_at) = rest.find(INPUT) else {
        return false;
    };
    let rest = &rest[input_at + INPUT.len()..];
    let Some(pipeline_at) = rest.find(PIPELINE) else {
        return false;
    };
    let Some(rest) = after_handle(&rest[pipeline_at + PIPELINE.len()..]) else {
        return false;
    };
    let named = format!("[{NAME}]{LAYOUT}");
    rest.starts_with(&named) && rest.trim_end().ends_with(ACCESSES)
}

/// What follows the hexadecimal digits a handle begins `text` with; `None` without any.
fn after_handle(text: &str) -> Option<&str> {
    let end = text
        .find(|c: char| !c.is_ascii_hexdigit())
        .unwrap_or(text.len());
    (end > 0).then(|| &text[end..])
}

/// Whether the layer release `version` is one whose source was read with the gap in place.
pub(super) fn read(version: u32) -> bool {
    READ.contains(&version)
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The message as the lanes saw it on lavapipe (Mesa, LLVM 23.1.1) with the layer 1.4.357,
    /// the runtime's name after the pipeline's handle (the layer prints an object's debug name
    /// there).
    fn seen() -> String {
        format!(
            "vkCmdDraw(): READ_AFTER_WRITE hazard detected. Shader stage \
             VK_SHADER_STAGE_FRAGMENT_BIT reads VkImageView 0x3d000000003d, which was previously \
             written by another vkCmdDraw command. \nThe image is referenced by descriptor \
             binding 1 (VK_DESCRIPTOR_TYPE_INPUT_ATTACHMENT) from descriptor set 0 \
             (VkDescriptorSet 0x0), VkPipeline 0x370000000037[{NAME}], image layout \
             VK_IMAGE_LAYOUT_GENERAL.\nNo sufficient synchronization is present to ensure that a \
             read (VK_ACCESS_2_INPUT_ATTACHMENT_READ_BIT) at \
             VK_PIPELINE_STAGE_2_FRAGMENT_SHADER_BIT does not conflict with a prior write \
             (VK_ACCESS_2_COLOR_ATTACHMENT_WRITE_BIT) at \
             VK_PIPELINE_STAGE_2_COLOR_ATTACHMENT_OUTPUT_BIT."
        )
    }

    #[test]
    fn the_layer_s_report_of_a_named_pipeline_s_input_attachment_read_is_the_gap() {
        assert!(shape(ID, ID_NAME, &seen()));
        // Reported for the last time, after the layer's note.
        let last = format!(
            "{LAST_TIME}10 times, which is the duplicate_message_limit value, this will be the \
             last time reporting it).\n{}",
            seen()
        );
        assert!(shape(ID, ID_NAME, &last));
        // Another draw command, at either end.
        let indexed = seen().replacen("vkCmdDraw(): ", "vkCmdDrawIndexed(): ", 1);
        let indexed = indexed.replace("another vkCmdDraw command", "vkCmdDraw");
        assert!(shape(ID, ID_NAME, &indexed));
        // Another binding, or an array element of one.
        let element = seen().replace(
            "binding 1 (VK_DESCRIPTOR_TYPE_INPUT_ATTACHMENT)",
            "binding 2 (VK_DESCRIPTOR_TYPE_INPUT_ATTACHMENT), array element 1",
        );
        assert!(shape(ID, ID_NAME, &element));
    }

    #[test]
    fn a_pipeline_without_the_name_is_not_the_gap() {
        let text = seen();
        let unnamed = text.replace(&format!("[{NAME}]"), "");
        assert!(!shape(ID, ID_NAME, &unnamed), "unnamed");
        let other = text.replace(NAME, "another pipeline");
        assert!(!shape(ID, ID_NAME, &other), "another name");
        let wider = text.replace(NAME, &format!("{NAME} and more"));
        assert!(!shape(ID, ID_NAME, &wider), "a wider name");
        // The name on the view, the pipeline unnamed.
        let elsewhere = unnamed.replace(
            "VkImageView 0x3d000000003d",
            &format!("VkImageView 0x3d000000003d[{NAME}]"),
        );
        assert!(!shape(ID, ID_NAME, &elsewhere), "the name on the view");
    }

    #[test]
    fn other_hazards_are_not_the_gap() {
        let text = seen();
        assert!(!shape(1544472022, "SYNC-HAZARD-WRITE-AFTER-WRITE", &text));
        assert!(!shape(ID, "SYNC-HAZARD-WRITE-AFTER-READ", &text));
        assert!(!shape(0, ID_NAME, &text));
        // Another descriptor: a sampled image or a storage image.
        for kind in [
            "VK_DESCRIPTOR_TYPE_SAMPLED_IMAGE",
            "VK_DESCRIPTOR_TYPE_STORAGE_IMAGE",
            "VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER",
        ] {
            let other = text.replace("VK_DESCRIPTOR_TYPE_INPUT_ATTACHMENT", kind);
            assert!(!shape(ID, ID_NAME, &other), "{kind}");
        }
        // An earlier write by no draw: a load op, a store op, a clear, a copy.
        for prior in [
            "at the beginning of subpass 0 (vkCmdBeginRenderPass) by the attachment loadOp",
            "at the end of the render pass instance (vkCmdEndRenderPass) by the attachment storeOp",
            "by vkCmdClearAttachments",
            "by vkCmdCopyBufferToImage",
        ] {
            let other = text.replace("by another vkCmdDraw command", prior);
            assert!(!shape(ID, ID_NAME, &other), "{prior}");
        }
        // Another read or write, or a barrier that orders part of them.
        let storage = text.replace(
            "a prior write (VK_ACCESS_2_COLOR_ATTACHMENT_WRITE_BIT) at \
             VK_PIPELINE_STAGE_2_COLOR_ATTACHMENT_OUTPUT_BIT",
            "a prior write (VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT) at \
             VK_PIPELINE_STAGE_2_FRAGMENT_SHADER_BIT",
        );
        assert!(!shape(ID, ID_NAME, &storage), "a storage write");
        let sampled = text.replace(
            "a read (VK_ACCESS_2_INPUT_ATTACHMENT_READ_BIT)",
            "a read (VK_ACCESS_2_SHADER_SAMPLED_READ_BIT)",
        );
        assert!(!shape(ID, ID_NAME, &sampled), "a sampled read");
        let at = text.find("No sufficient").unwrap();
        let partial = format!(
            "{}The current synchronization allows COLOR_ATTACHMENT_WRITE accesses at \
             COLOR_ATTACHMENT_OUTPUT, but to prevent this hazard, it must allow \
             VK_ACCESS_2_INPUT_ATTACHMENT_READ_BIT accesses at \
             VK_PIPELINE_STAGE_2_FRAGMENT_SHADER_BIT.",
            &text[..at]
        );
        assert!(!shape(ID, ID_NAME, &partial), "a partial barrier");
        // Found at a dispatch, a copy, or the shader's read of another stage.
        let dispatch = text.replacen("vkCmdDraw(): ", "vkCmdDispatch(): ", 1);
        assert!(!shape(ID, ID_NAME, &dispatch), "a dispatch");
        let vertex = text.replace("VK_SHADER_STAGE_FRAGMENT_BIT", "VK_SHADER_STAGE_VERTEX_BIT");
        assert!(!shape(ID, ID_NAME, &vertex), "the vertex stage");
        // Anything else before the command's line.
        let before = format!("Something else.\n{text}");
        assert!(!shape(ID, ID_NAME, &before), "another preface");
    }

    #[test]
    fn only_the_releases_read_pass() {
        assert!(read(vk::make_api_version(0, 1, 4, 357)));
        assert!(read(vk::make_api_version(0, 1, 4, 363)));
        assert!(!read(vk::make_api_version(0, 1, 4, 356)));
        assert!(!read(vk::make_api_version(0, 1, 4, 358)));
        assert!(!read(vk::make_api_version(0, 1, 5, 0)));
    }
}
